"css`
        :host {
            display: flex;
            flex: 1 1 0;
            flex-flow: column nowrap;
            padding: 0;
        }
        div#content-area {
            display: flex;
            flex: 1 1 0;
            align-content: start;
            flex-flow: row nowrap;
            position: relative;
        }
        div#toolbar {
            display: flex;
            flex-flow: column nowrap;
            align-items: center;
            width: 48px;
            background-color: var(--sl-color-gray-400);
        }

        table {
            margin: 0;
            font-size: var(--sl-font-size-x-small);
        }

        /* Group table container and sub-container */
        div#groups {
            display: flex;
            flex-flow: column nowrap;
            flex: 1 1 0;
        }
        div#groups > div {
            display: flex;
            flex-flow: column nowrap;
            flex: 1 1 0;
            overflow-y: scroll;
        }
        
        /* Group table formatting */
        table#group-table > thead th {
            position: sticky;
            top: 0;
            background-color: gray;
            z-index: 1;
        }
        
        /* Variant table and row styles */
        div.variants {
            display: flex;
            margin-left: 2em;
            margin-right: 2em;
            flex-flow: column wrap;
            align-content: center;
            justify-content: center;
            background-color: var(--sl-color-primary-100);
        }
        div.variants > table {
            width: fit-content;
            border-collapse: separate;
            border-spacing: 4em 2px;
        }
        
        td.dependant-cover {
            text-align: center;
        }
        
        /* Spinner style */
        sl-spinner {
            position: absolute;
            top:  50%;
            left: 50%;
            transform: translate(-50%,-50%);
            font-size: 64px; 
            --track-width: 12px;
        }
    `"

